// GENERATED by mod/build.mjs from src/translate.js. Do not edit.
// Rule-based translation of steps into three levels of detail:
//   simple    plain English, a few words ("Building the top card")
//   vibe      friendlier summary with file names and what changed
//   engineer  the actual call: tool, command or diff, and output
//
// Unknown tools get a generic description. If AI fallback is on, ai.js may
// later replace simple/vibe for those (step.ai).

import path from './pathshim.js';
import { clip } from './pathshim.js';

const ENG_LIMIT = 2500;

// ---------------------------------------------------------------------------
// Friendly names for files

const SPECIAL_FILES = {
  'package.json': 'package settings',
  'package-lock.json': 'package lockfile',
  'tsconfig.json': 'TypeScript settings',
  '.gitignore': 'git ignore list',
  'readme.md': 'README',
  'dockerfile': 'Docker setup',
  'claude.md': 'Claude instructions',
  '.env': 'environment settings',
};
const GENERIC_BASENAMES = new Set(['index', 'main', 'mod', '__init__', 'page', 'layout', 'route', 'app', 'default']);

function words(s) {
  return s
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
    .replace(/[-_.]+/g, ' ')
    .trim()
    .toLowerCase();
}

/** "src/components/TopCard.tsx" -> "top card" */
export function friendlyName(file) {
  if (!file) return 'a file';
  const base = path.basename(file);
  const special = SPECIAL_FILES[base.toLowerCase()];
  if (special) return special;
  let stem = base.replace(/\.[^.]+$/, '');
  const testMatch = /^(.*?)[._-](test|spec)$/i.exec(stem);
  if (testMatch) return `tests for the ${words(testMatch[1])}`;
  if (GENERIC_BASENAMES.has(stem.toLowerCase())) {
    const parent = path.basename(path.dirname(file));
    if (parent && parent !== '.' && parent !== '/') stem = `${parent} ${stem.toLowerCase() === 'index' ? '' : stem}`;
  }
  return words(stem) || base;
}

function fileKind(file) {
  const ext = path.extname(file || '').toLowerCase();
  const base = path.basename(file || '').toLowerCase();
  if (/[._-](test|spec)\.[^.]+$/.test(base) || /(^|\/)(__tests__|tests?)\//.test(file || '')) return 'test';
  if (['.tsx', '.jsx', '.vue', '.svelte', '.astro'].includes(ext)) return 'ui';
  if (['.css', '.scss', '.sass', '.less'].includes(ext)) return 'style';
  if (['.md', '.mdx', '.txt', '.rst'].includes(ext)) return 'doc';
  if (['.json', '.yaml', '.yml', '.toml', '.ini', '.env'].includes(ext) || base.startsWith('.')) return 'config';
  return 'code';
}

function short(file, cwd) {
  if (!file) return '';
  if (cwd && file.startsWith(cwd + '/')) return file.slice(cwd.length + 1);
  const home = (typeof process === 'undefined' ? undefined : process.env.HOME);
  if (home && file.startsWith(home + '/')) return '~/' + file.slice(home.length + 1);
  return file;
}

const q = (s, n = 40) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
};
const lineCount = (s) => (typeof s === 'string' && s ? s.split('\n').length : 0);
const plural = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;

// ---------------------------------------------------------------------------
// Shell commands

const SHELL_RULES = [
  [/\b(npm|pnpm|yarn|bun)\s+(run\s+)?test\b|\b(jest|vitest|pytest|mocha|go test|cargo test|rspec|phpunit)\b|node\s+--test/, 'test', 'Running the tests'],
  [/\b(npm|pnpm|yarn|bun)\s+(i|install|add|ci)\b|\bpip3?\s+install\b|\bbrew\s+install\b|\bcargo\s+add\b|\bgo\s+get\b/, 'install', 'Installing packages'],
  [/\b(npm|pnpm|yarn|bun)\s+run\s+(build|compile)\b|\b(tsc|webpack|vite\s+build|cargo\s+build|go\s+build|make)\b/, 'build', 'Building the project'],
  [/\b(npm|pnpm|yarn|bun)\s+run\s+(dev|start|serve)\b|\b(vite|next\s+dev)\b/, 'run', 'Starting the app'],
  [/\b(eslint|prettier|ruff|black|biome|npm run lint)\b/, 'lint', 'Tidying up the code'],
  [/\bgit\s+commit\b/, 'git', 'Saving a checkpoint'],
  [/\bgit\s+push\b/, 'git', 'Uploading the changes'],
  [/\bgit\s+(pull|fetch|merge|rebase)\b/, 'git', 'Syncing with the repository'],
  [/\bgit\s+(checkout|switch|branch)\b/, 'git', 'Switching branches'],
  [/\bgit\s+(status|diff|log|show)\b/, 'git', 'Checking what changed'],
  [/\bgh\s+pr\b/, 'git', 'Working on the pull request'],
  [/\b(curl|wget|http)\b/, 'web', 'Fetching from the web'],
  [/^\s*(mkdir)\b/, 'files', 'Making a folder'],
  [/^\s*(rm|rmdir)\b/, 'files', 'Removing files'],
  [/^\s*(mv|cp)\b/, 'files', 'Moving files around'],
  [/^\s*(ls|find|tree|pwd|du)\b/, 'look', 'Looking around the project'],
  [/^\s*(cat|head|tail|less|sed\s+-n|wc)\b/, 'read', 'Reading a file'],
  [/^\s*(grep|rg|ag)\b/, 'search', 'Searching the code'],
  [/\b(docker|kubectl|terraform)\b/, 'build', 'Working with infrastructure'],
  [/^\s*(node|python3?|deno|ruby|go\s+run|bash|sh)\b/, 'run', 'Running a script'],
];

function classifyShell(cmd) {
  const c = String(cmd || '').replace(/^\s*cd\s+[^&;]+(&&|;)\s*/, '');
  for (const [re, kind, phrase] of SHELL_RULES) if (re.test(c)) return { kind, phrase };
  return { kind: 'shell', phrase: 'Running a command' };
}

// ---------------------------------------------------------------------------
// Tools

// "session" -> "session code" for plain source files, so the sentence reads.
function nounFor(file) {
  const noun = friendlyName(file);
  const special = SPECIAL_FILES[path.basename(file || '').toLowerCase()];
  return fileKind(file) === 'code' && !special ? `${noun} code` : noun;
}

function verbForEdit(file) {
  switch (fileKind(file)) {
    case 'ui': return 'Building';
    case 'style': return 'Styling';
    case 'test': return 'Writing';
    case 'doc': return 'Writing';
    case 'config': return 'Adjusting';
    default: return 'Updating';
  }
}

function outcome(step) {
  if (step.status === 'running') return '';
  if (step.blockedByFix) return ' — stopped by your fix';
  if (step.status === 'error') return ' — hit a snag';
  return '';
}

function mcpParts(name) {
  const m = /^mcp__(.+?)__(.+)$/.exec(name);
  return m ? { server: m[1].replace(/^plugin_[^_]+_/, ''), tool: m[2] } : null;
}

/**
 * @returns {{icon:string, cat:string, simple:string, vibe:string, known:boolean}}
 */
function describeTool(step, cwd) {
  const i = step.input || {};
  const r = step.result || {};
  const name = step.name;
  const file = i.file_path || i.notebook_path || i.path;
  const rel = short(file, cwd);
  const noun = friendlyName(file);
  const done = step.status !== 'running';

  switch (name) {
    case 'Read':
      return {
        icon: 'read', cat: 'read', known: true,
        simple: `Reading the ${noun}`,
        vibe: `Read \`${rel}\`` + (i.offset ? ` from line ${i.offset}` : '') + (r.numLines ? ` (${plural(r.numLines, 'line')})` : ''),
      };
    case 'Write': {
      const created = r.type ? r.type === 'create' : null;
      const n = lineCount(i.content);
      return {
        icon: 'create', cat: 'write', known: true,
        simple: `${created === false ? 'Rewriting' : 'Creating'} the ${nounFor(file)}`,
        vibe: `${created === false ? 'Rewrote' : 'Created'} \`${rel}\` — ${plural(n, 'line')}`,
      };
    }
    case 'Edit':
    case 'MultiEdit': {
      const edits = name === 'MultiEdit' && Array.isArray(i.edits) ? i.edits : [i];
      const removed = r.removed ?? edits.reduce((a, e) => a + lineCount(e.old_string), 0);
      const added = r.added ?? edits.reduce((a, e) => a + lineCount(e.new_string), 0);
      return {
        icon: 'edit', cat: 'write', known: true,
        simple: `${verbForEdit(file)} the ${nounFor(file)}`,
        vibe: `Changed \`${rel}\` — ${!added ? `removed ${plural(removed, 'line')}` : !removed ? `added ${plural(added, 'line')}` : `swapped ${plural(removed, 'line')} for ${added}`}${i.replace_all ? ' (everywhere)' : ''}`,
      };
    }
    case 'NotebookEdit':
      return { icon: 'edit', cat: 'write', known: true, simple: `Editing the ${noun} notebook`, vibe: `Edited a cell in \`${rel}\`` };
    case 'Bash': {
      const { kind, phrase } = classifyShell(i.command);
      const exit = step.status === 'error' ? ' → failed' : done ? ' → ok' : '';
      const bg = i.run_in_background ? ' (in the background)' : '';
      return {
        icon: kind === 'test' ? 'test' : kind === 'install' ? 'package' : kind === 'git' ? 'git' : kind === 'web' ? 'globe' : 'terminal',
        cat: kind === 'test' ? 'test' : 'run', known: true,
        simple: phrase + bg,
        vibe: (i.description ? i.description : `Ran \`${q(i.command, 60)}\``) + bg + exit,
      };
    }
    case 'BashOutput':
      return { icon: 'terminal', cat: 'run', known: true, simple: 'Checking on a running command', vibe: 'Read output from a background command' };
    case 'KillShell':
    case 'KillBash':
      return { icon: 'terminal', cat: 'run', known: true, simple: 'Stopping a running command', vibe: 'Stopped a background command' };
    case 'Grep':
      return {
        icon: 'search', cat: 'search', known: true,
        simple: `Searching the code for “${q(i.pattern, 30)}”`,
        vibe: `Searched for “${q(i.pattern, 50)}”${i.path ? ` in \`${short(i.path, cwd)}\`` : ''}${r.numFiles != null ? ` — ${plural(r.numFiles, 'file')}` : ''}`,
      };
    case 'Glob':
      return {
        icon: 'search', cat: 'search', known: true,
        simple: 'Finding files',
        vibe: `Looked for files matching \`${q(i.pattern, 50)}\`${r.numFiles != null ? ` — ${plural(r.numFiles, 'match')}` : ''}`,
      };
    case 'LS':
      return { icon: 'folder', cat: 'search', known: true, simple: 'Looking around the project', vibe: `Listed \`${rel || '.'}\`` };
    case 'WebSearch':
      return { icon: 'globe', cat: 'web', known: true, simple: `Searching the web for “${q(i.query, 30)}”`, vibe: `Searched the web: “${q(i.query, 70)}”` };
    case 'WebFetch': {
      let host = '';
      try {
        host = new URL(i.url).host;
      } catch {}
      return { icon: 'globe', cat: 'web', known: true, simple: `Reading ${host || 'a web page'}`, vibe: `Read ${q(i.url, 70)}` };
    }
    case 'Task':
    case 'Agent':
      return {
        icon: 'agent', cat: 'agent', known: true,
        simple: `Sending a helper to ${lowerFirst(q(i.description || 'help', 40))}`,
        vibe: `Started a ${i.subagent_type || 'helper'} agent: ${q(i.description || i.prompt, 80)}`,
      };
    case 'TodoWrite':
    case 'TaskCreate':
    case 'TaskUpdate':
    case 'mcp__ccd_turn__update_plan': {
      const items = i.todos || i.items || [];
      const active = Array.isArray(items) ? items.find((t) => t.status === 'in_progress') : null;
      return {
        icon: 'list', cat: 'plan', known: true,
        simple: active ? `Next up: ${lowerFirst(q(active.content || active.activeForm, 40))}` : 'Updating the to-do list',
        vibe: Array.isArray(items) && items.length
          ? `Plan: ${items.filter((t) => t.status === 'completed').length}/${items.length} done${active ? ` · now: ${q(active.content || active.activeForm, 60)}` : ''}`
          : 'Updated the to-do list',
      };
    }
    case 'AskUserQuestion':
      return { icon: 'question', cat: 'ask', known: true, simple: 'Asking you a question', vibe: `Asked: ${q(i.questions?.[0]?.question, 90)}` };
    case 'ExitPlanMode':
      return { icon: 'list', cat: 'plan', known: true, simple: 'Showing you the plan', vibe: 'Proposed a plan for your approval' };
    case 'EnterPlanMode':
      return { icon: 'list', cat: 'plan', known: true, simple: 'Planning', vibe: 'Switched to planning' };
    case 'Skill':
      return { icon: 'spark', cat: 'tool', known: true, simple: `Using the ${q(i.skill || i.name, 30)} skill`, vibe: `Loaded skill “${q(i.skill || i.name, 40)}”` };
    case 'ToolSearch':
      return { icon: 'plug', cat: 'tool', known: true, simple: 'Looking up tools', vibe: `Loaded tools: ${q(i.query, 60)}` };
  }

  const mcp = mcpParts(name);
  if (mcp) {
    return {
      icon: 'plug', cat: 'tool', known: false,
      simple: `Using ${words(mcp.server)}: ${words(mcp.tool)}`,
      vibe: `Called ${words(mcp.tool)} on ${mcp.server}`,
    };
  }
  return { icon: 'plug', cat: 'tool', known: false, simple: `Using ${words(name)}`, vibe: `Used the ${name} tool` };
}

function lowerFirst(s) {
  return s ? s[0].toLowerCase() + s.slice(1) : s;
}

function firstSentence(text, n) {
  const t = text.replace(/[#*_`>]/g, '').replace(/\s+/g, ' ').trim();
  const m = /^(.{12,}?[.!?])(\s|$)/.exec(t);
  return q(m ? m[1] : t, n);
}

// ---------------------------------------------------------------------------
// Engineer detail

function engineer(step, cwd) {
  if (step.kind !== 'tool') return { title: step.kind, body: clip(step.text || '', ENG_LIMIT), lang: 'text' };
  const i = step.input || {};
  let title = step.name;
  let body = '';
  let lang = 'text';
  const file = i.file_path || i.notebook_path;
  if (step.name === 'Bash') {
    title = `$ ${q(i.command, 120)}`;
    body = `$ ${i.command}`;
    lang = 'shell';
  } else if (step.name === 'Edit') {
    title = `Edit ${short(file, cwd)}`;
    body = diff(i.old_string, i.new_string);
    lang = 'diff';
  } else if (step.name === 'MultiEdit' && Array.isArray(i.edits)) {
    title = `MultiEdit ${short(file, cwd)} (${i.edits.length})`;
    body = i.edits.map((e) => diff(e.old_string, e.new_string)).join('\n@@\n');
    lang = 'diff';
  } else if (step.name === 'Write') {
    title = `Write ${short(file, cwd)}`;
    body = i.content || '';
    lang = 'code';
  } else if (step.name === 'Read') {
    title = `Read ${short(file, cwd)}${i.offset ? ` @${i.offset}` : ''}${i.limit ? `+${i.limit}` : ''}`;
  } else {
    const args = Object.entries(i)
      .map(([k, v]) => `${k}: ${typeof v === 'string' ? v : JSON.stringify(v)}`)
      .join('\n');
    title = `${step.name}(${q(Object.values(i).filter((v) => typeof v === 'string')[0] || '', 60)})`;
    body = args;
  }
  return {
    title,
    body: clip(body, ENG_LIMIT),
    lang,
    output: step.output ? clip(step.output, ENG_LIMIT) : step.status === 'running' ? '' : '(no output)',
    stderr: step.result?.stderr || '',
  };
}

function diff(oldS = '', newS = '') {
  const minus = String(oldS).split('\n').map((l) => '- ' + l);
  const plus = String(newS).split('\n').map((l) => '+ ' + l);
  return [...(oldS ? minus : []), ...plus].join('\n');
}

// ---------------------------------------------------------------------------

/** Adds .view = {icon, cat, simple, vibe, eng, known} to a copy of the step. */
export function translate(step, { cwd, ai } = {}) {
  let v;
  if (step.kind === 'prompt') {
    v = { icon: 'user', cat: 'you', known: true, simple: `You asked: ${firstSentence(step.text, 70)}`, vibe: q(step.text, 220) };
  } else if (step.kind === 'command') {
    v = { icon: 'slash', cat: 'you', known: true, simple: `You ran ${q(step.text, 40)}`, vibe: `Ran the ${q(step.text, 60)} command` };
  } else if (step.kind === 'message') {
    v = { icon: 'chat', cat: 'say', known: true, simple: firstSentence(step.text, 90), vibe: q(step.text, 320) };
  } else if (step.kind === 'fix') {
    v = {
      icon: 'flag', cat: 'fix', known: true,
      simple: `You steered: ${q(step.text, 60)}`,
      vibe: `${step.urgency === 'urgent' ? 'Urgent fix' : 'Fix'}: ${q(step.text, 200)}${step.doing ? ` (while it ${step.doing.replace(/^about to run/, 'was about to run')})` : ''}`,
    };
  } else {
    v = describeTool(step, cwd);
    const extra = outcome(step);
    if (!v.known && ai) {
      v.simple = ai.simple || v.simple;
      v.vibe = ai.vibe || v.vibe;
      v.ai = true;
    }
    v.vibe += extra;
  }
  v.eng = engineer(step, cwd);
  const { input, ...rest } = step;
  return { ...rest, view: v };
}

export const _test = { classifyShell, words };
